import java.util.*;

class Solution {
    public int countMoves(long n) {
        int moves = 0;
        while (n > 0) {
            if (n % 2 == 0) n /= 2;   // even: halve
            else n -= 1;               // odd: step down
            moves++;
        }
        return moves;
    }
}

